import { apiClient } from "./client";
import { Permission, PermissionListRaw } from "./types";

// The catalogue is generated by the backend from the modules it has loaded.
// Never hardcode permissions on the client.
export const listPermissionCatalogueApi = async (): Promise<Permission[]> => {
  const resp = await apiClient.get<PermissionListRaw>("/v1/permissions");
  return resp.data?.items || [];
};
